# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# sanity_fims ----
## Setup ----
if (!file.exists(testthat::test_path("fixtures", "fit_age_length_comp.RDS"))) {
  suppressWarnings(
    suppressMessages(
      prepare_test_data()
    )
  )
}
fit_age_length_comp <- readRDS(
  testthat::test_path("fixtures", "fit_age_length_comp.RDS")
)

## IO correctness ----
test_that("sanity_fims() works with correct inputs", {
  #' @description Test that sanity_fims() returns all_ok = TRUE and the stored checks for a converged fit.
  expect_message(
    sanity <- sanity_fims(fit_age_length_comp),
    regexp = "checks are OK"
  )
  expect_true(sanity[["all_ok"]])
  expect_equal(sanity[["checks"]], get_convergence(fit_age_length_comp))
})

## Edge handling ----
test_that("sanity_fims() returns correct outputs for edge cases", {
  #' @description Test that sanity_fims() returns all_ok = FALSE and names the flagged checks when a check did not pass.
  flagged_fit <- fit_age_length_comp
  flagged_fit@convergence[["severity"]][
    flagged_fit@convergence[["check"]] == "condition_number"
  ] <- "WARN"
  expect_message(
    sanity <- sanity_fims(flagged_fit),
    regexp = "1 of 7 checks need attention"
  )
  expect_false(sanity[["all_ok"]])

  #' @description Test that sanity_fims() returns all_ok = FALSE when no checks were stored, as for a fit with optimize = FALSE.
  not_optimized_fit <- fit_age_length_comp
  not_optimized_fit@convergence <- not_optimized_fit@convergence[0, ]
  expect_message(
    sanity <- sanity_fims(not_optimized_fit),
    regexp = "model was not"
  )
  expect_false(sanity[["all_ok"]])
})

## Error handling ----
test_that("sanity_fims() returns correct error messages", {
  #' @description Test that sanity_fims() errors when the input is not a FIMSFit object.
  expect_error(
    object = sanity_fims(list()),
    regexp = "must be a"
  )
})
